INSERT INTO `sameepaccounting_proforma_invoice` (`invoice_id`, `invoice_number`, `invoice_date`, `customer_id`, `product_name`, `quantity`, `unit`, `hsn_code`, `gst`, `sgst`, `cgst`, `igst`, `gst_type`, `price`, `amount`, `description`, `uid`, `barcode`, `discount`) VALUES
(1, 'PROFORMAINV/0001/APR/22-23', '2022-04-13', 217, 'STYLE DOOR  45X75 BLACK STICKSERIES FLUTE GLASS ', 250, 'SQFT', '99547', '18%', 0, 0, 2025000, 'I', 45000, 11250000, '<p>PROVIDING AND FIXING 10MM FLUTE TOUGHENED GLASS&nbsp;</p>\r\n\r\n<p>ARCON DOOR FRAMESIZE 55MMX55MM&nbsp;WITH STYLE DOOR 45MMX75MM PROFILE WITH GASKET</p>\r\n\r\n<p>GLASS DOOR HARDWARES- (<strong>BLACK)</strong></p>\r\n\r\n<p>ORNO MORTICE HANDLE</p>\r\n\r\n<p>ORNO LOCK BODY WITH CYLINDER</p>\r\n\r\n<p>ORNO HINGES</p>\r\n\r\n<p>GEZE CONCEALE DOOR CLOSER</p>\r\n\r\n<p>ORNO DROP DOWN SEAL&nbsp;</p>\r\n', 1, '', 0),
(2, 'PROFORMAINV/0001/APR/22-23', '2022-04-13', 217, 'UNIQUELINE 2545  FOLDING MALE BLACK 5900 MM', 250, 'NOS', '7610', '18%', 0, 0, 0, 'I', 0, 0, '<p>ARCON UNIQUELINE FOLDING PROFILE MALE BALCK</p>\r\n', 1, '', 0),
(3, 'PROFORMAINV/0002/APR/22-23', '2022-04-13', 224, 'UNIQUELINE', 250, 'SQFT', '99547', '18%', 0, 0, 13500, 'I', 300, 75000, '<p>PROVIDING AND FIXING ARCON MODULAR FULL HEIGHT GLASS PARTITION SYSTEM</p>\r\n\r\n<p>UNIQUELINE-25MM X 45MM PROFILE ,</p>\r\n\r\n<p><strong>SILVER ANODIZE</strong>,</p>\r\n\r\n<p>INCLUDING GLASS TO GLASS I, T, L JOINT AND GASKETS, WITH 10MM CLEAR TOUGHENED GLASS.</p>\r\n\r\n<p>SOUND INSULATION CAPACITY OF 28-32 DB<br />\r\n&nbsp;</p>\r\n', 1, '', 0),
(4, 'PROFORMAINV/0002/APR/22-23', '2022-04-13', 224, 'STYLE SLIDING DOOR 45X75  ', 300, 'NOS', '99547', '18%', 0, 0, 1890000, 'I', 35000, 10500000, '<p>PROVIDING AND FIXING 08MM CLEAR TOUGHENED GLASS&nbsp;</p>\r\n\r\n<p>ARCON STYLE DOOR&nbsp; -STYLE DOOR 45MMX75MM PROFILE WITH GASKET</p>\r\n\r\n<p><strong>SILVER ANODIZE</strong></p>\r\n\r\n<p>GLASS DOOR HARDWARES-&nbsp;</p>\r\n\r\n<p>&nbsp;TRACK FOR SLIDING SYSTEM&nbsp;</p>\r\n\r\n<p>SLIDING ROLLER COMBO SET&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n', 1, '', 0),
(5, 'PROFORMAINV/0001/JUL/23-24', '2023-07-06', 252, ' RENO', 1, 'SQFT', '99547', '18%', 0, 0, 99, 'I', 550, 550, '<p>PROVIDING AND FIXING ARCON MODULAR FULL HEIGHT GLASS PARTITION SYSTEM</p>\r\n\r\n<p>DOUBLE AND OFFSET GLAZED RENO-25MM X 55MM PROFILE ,</p>\r\n\r\n<p><strong>SILVER ANODIZE,</strong></p>\r\n\r\n<p>INCLUDING GLASS TO GLASS I, T, L JOINT AND GASKETS, WITH 10MM CLEAR TOUGHENED GLASS.</p>\r\n\r\n<p>SOUND INSULATION CAPACITY OF OFFSET 32-36 DB AND DOUBLE GLASS 46-52 DB</p>\r\n', 1, '', 0),
(6, 'PROFORMAINV/0001/AUG/24-25', '2024-08-22', 317, 'Visitor Management Software', 1, 'NOS', '9983', '18%', 3150, 3150, 0, 'S', 35000, 35000, '<p>Visitor Management Software with customization. (Deployment on Xform Server)</p>\r\n\r\n<p>&nbsp;</p>\r\n', 1, '', 0),
(7, 'PROFORMAINV/0001/AUG/24-25', '2024-08-22', 317, 'Server Charges', 1, 'NOS', '9883', '18%', 720, 720, 0, 'S', 8000, 8000, '  Server Charges for 1 year.\r\n\r\nNote: Pricing may change due to an increase in your server usage or a price adjustment on the part of the server provider', 1, '', 0),
(8, 'PROFORMAINV/0001/AUG/24-25', '2024-08-22', 317, 'SMS Gateway  10000 sms for 1 year', 1, 'NOS', '9883', '18%', 315, 315, 0, 'S', 3500, 3500, 'Note: If 10,000 SMS are used up before the end of the year, you need to purchase additional SMS.', 1, '', 0);
