INSERT INTO `sameepaccounting_settings` (`setting_id`, `company_logo`, `quotation_subheading`, `quotation_title`, `quotation_footer`, `quotation_memo`, `invoice_default_payment_term`, `invoice_title`, `invoice_subheading`, `invoice_footer`, `invoice_memo`, `invoice_notes`, `address`, `state_code`, `company_name`, `company_gst`, `company_pan`, `notes`, `po_title`, `po_subheading`, `po_footer`, `po_memo`, `po_note`, `mobile`, `email`, `uid`, `terms_and_conditions`, `payment_terms`, `process_schedule`, `taxes`, `exclusions`, `po_terms_and_conditions`, `po_payment_terms`, `po_process_schedule`, `po_taxes`, `po_exclusions`, `cin`, `company_stamp`, `purchase_requisition_notes`) VALUES
(1, './uploads/logo.jpg', '', '', 'Arcon Partition', '', '1', '', '', '         A302, Kamalraj Balaji Residency, Dighi                         ', '1. Scope of requirement may change application cost will be change in future.\r\n\r\n2. Payment Terms\r\n-Advance 70% required before work start.\r\n\r\n3. GST Number: 27AAACX1482C1ZJ', 'Payment by: Cheque or Online Transfer Company Bank Account Details for\r\nOnline Transfer Name: Xform Technologies Private Limited Account No: 0668102000008075\r\nIFSC Code: IBKL0000668\r\nAccount Type: Current Account\r\nBranch: IDBI Bank, S. N. 39/3, Siddheshwar, Tingre Nagar Road, Pune-411015\r\nCheque will be drawn “Xform Technologies Private Limited” and sent to our company address', 'A302, Kamalraj Balaji Residency,\r\nDighi\r\nPune, Maharashtra 411015\r\nIndia', '27', 'Xform Technologies Private Limited', '27AAACX1482C1ZJ', 'AAACX1482C', '', '', '', '                                       ', '', '', '9890726453', 'contact@xform.in', 1, '<p><span style=\"font-size:11px\"><strong>Transportation</strong></span></p>\r\n\r\n<ol>\r\n	<li>\r\n	<p><span style=\"font-size:11px\">Cost of transportation from our warehouse to your designated warehouse or project site is&nbsp; &nbsp;payable extra and is not included in quoted price (unless specified)</span></p>\r\n	</li>\r\n</ol>\r\n\r\n<p><span style=\"font-size:11px\"><strong>Packaging</strong></span></p>\r\n\r\n<ol>\r\n	<li>\r\n	<p><span style=\"font-size:11px\">&nbsp;Cost of normal packaging in corrugated carton/wrapping is included in quoted price but does not&nbsp; &nbsp;cover cost of wooden crating, palletisation, weather proof packing or any other special packing&nbsp; &nbsp; &nbsp;or fumigation charges.</span></p>\r\n	</li>\r\n</ol>\r\n\r\n<p><span style=\"font-size:11px\"><strong>Loading/unloading/handling</strong></span></p>\r\n\r\n<ol>\r\n	<li>\r\n	<p><span style=\"font-size:11px\">&nbsp;Cost of one time loading in our warehouse is included in quoted price cost of&nbsp; &nbsp;unloading at your&nbsp; &nbsp;designated warehouse or project site is not included in quoted&nbsp; &nbsp;price.</span></p>\r\n	</li>\r\n	<li>\r\n	<p><span style=\"font-size:11px\">&nbsp;In case of unloading is included and specifically mentioned in our quote, it shall&nbsp; &nbsp;be only at&nbsp; &nbsp;ground floor level nearest to the entrance.</span></p>\r\n	</li>\r\n</ol>\r\n\r\n<p><span style=\"font-size:11px\"><strong>Unloading by mathadi</strong></span></p>\r\n\r\n<ol>\r\n	<li>\r\n	<p><span style=\"font-size:11px\">&nbsp;Unloading by local mathadi/or any labor union member is at your cost and risk,&nbsp; &nbsp;we shall not&nbsp; &nbsp;interact/engage in any dealing with them of any kind for loading and&nbsp; &nbsp;handling of goods.</span></p>\r\n	</li>\r\n</ol>\r\n', '<ol>\r\n	<li><span style=\"font-size:11px\">&nbsp;50% ADVANCE,40% BEFOR GLASS,10% AFTER COMPLETION (INCLUDING GST AMOUNT)</span></li>\r\n	<li><span style=\"font-size:11px\">&nbsp;Payment shall be in favour of &quot;ARCON PARTITION&quot;</span></li>\r\n	<li><span style=\"font-size:11px\">&nbsp;There is No retention on behalf of &quot;ARCON PARTITION&quot;</span></li>\r\n</ol>\r\n\r\n<p><span style=\"font-size:11px\"><strong><span style=\"background-color:#00FFFF\">Delay in project schedule</span></strong></span></p>\r\n\r\n<ol>\r\n	<li><span style=\"font-size:11px\">&nbsp;On changing of approved specification by the client</span></li>\r\n	<li><span style=\"font-size:11px\">&nbsp;On delay in approval of samples,</span></li>\r\n	<li><span style=\"font-size:11px\">&nbsp;On non-receipt of payment in scheduled time by the client</span></li>\r\n	<li><span style=\"font-size:11px\">&nbsp;On noncompliance of site handover or any local authority or legal approval</span></li>\r\n	<li><span style=\"font-size:11px\">&nbsp;Due to natural calamity, strike, traffic problem not attributed to system installer</span></li>\r\n</ol>\r\n', '<p><span style=\"font-size:11px\"><strong>Installation</strong></span></p>\r\n\r\n<ol>\r\n	<li><span style=\"font-size:11px\">&nbsp;Installation unless specifically mentioned in this offer, is not in our scope and is not included in&nbsp; &nbsp;the quoted price</span></li>\r\n	<li><span style=\"font-size:11px\">&nbsp;Where installation is part of our scope same shall be specifically mentioned in our office and&nbsp; &nbsp;such installation shall not include any types of civil work whatsoever in our civil works, if any&nbsp; &nbsp;shall be scope of customer.</span></li>\r\n	<li><span style=\"font-size:11px\">&nbsp;Arcon&nbsp;partition system work will start only after clearance of full site, means no part work will be done, once started Arcon partition system will finish in single trough.</span></li>\r\n	<li><span style=\"font-size:11px\">&nbsp;Any changing in drawing or verbal communication at site will not be accepted until it is done on mail along with designated person only.</span></li>\r\n	<li><span style=\"font-size:11px\">&nbsp;We are taking glass pannel width in partition upto 1200 mm only,if changes in above width&nbsp; &nbsp;required at site than inform us before glass measurment,if any additional cost arise from this will not be paid by us</span></li>\r\n	<li><span style=\"font-size:11px\"><span style=\"background-color:#FF0000\">GLASS WILL BE HAVING BEND UPTO 1MM TO 6MM PER MTR</span></span></li>\r\n	<li><span style=\"font-size:11px\"><span style=\"background-color:#FF0000\">&nbsp;INSTALLATION SCHEDULE IS SUBJECT TO PAYMENT</span></span></li>\r\n	<li><span style=\"font-size:11px\">Delivery Schedule : 15 days after receiving PO and advance</span></li>\r\n	<li><span style=\"font-size:11px\">Validity of Quotation: 15 Days from the date of this quotation</span></li>\r\n</ol>\r\n', '<ol>\r\n	<li><span style=\"font-size:12px\">&nbsp;Gst is payable extra as actual, if not included in quote</span></li>\r\n	<li><span style=\"font-size:12px\">&nbsp;Any other levies and taxes, if any as mandated by the statuary authorities from time to time, at time of placing of order shall be payable extra, and is not included in quoted price (unless specified)</span></li>\r\n</ol>\r\n', '<p><span style=\"font-size:11px\"><strong>Security for physical material</strong></span></p>\r\n\r\n<ol>\r\n	<li><span style=\"font-size:11px\">It is the responsibility of the client for security of physical material lying at site. The liability from our side ceases as soon as the acknowledged of receipt of physical material duly signed by authorized representative of client. Once the duly acknowledged received at site will not be returnable under any circumstances</span></li>\r\n</ol>\r\n\r\n<p><span style=\"font-size:11px\"><strong>Jurisdiction</strong></span></p>\r\n\r\n<ol>\r\n	<li><span style=\"font-size:11px\">All disputes shall be subject to Mumbai jurisdiction only</span></li>\r\n</ol>\r\n', '', '', '', '', '', 'U72500PN2013PTC149350', './uploads/londhe_sign.jpg', 'All purchases must comply with the specifications mentioned in the requisition. Prices are exclusive of applicable taxes unless otherwise stated. Suppliers are required to ensure proper packaging and timely delivery of goods. Any deviations from the requisition must be approved in writing by the procurement department. Partial deliveries may be accepted only with prior consent. Invoices must reference the Purchase Requisition number for proper processing. Warranty, after-sales service, and any relevant certifications should accompany the delivery. Discrepancies, damages, or shortages must be reported immediately to the requesting department to facilitate resolution. For urgent items, suppliers are expected to coordinate delivery directly with the designated requestor.'),
(4, './uploads/xform-logo.jpg', '', '', '12/28, D1 Block, MIDC, chinchwad\r\n\r\nPune, Maharash...', '', '1', '', '', 'B Wing, 202, Sai Miracle Building, Near Akash ganga Society, Shivar Vihar, Rahatani, Pune, Maharasht', 'Payment should be done by NEFT/RTGS/Cheque in favour of  Vari Pontoons Pvt Ltd.  before due date, otherwise late payment charges may be applied @24%PM.   ', 'Saraswat Co-Operative Bank LTD\r\nA/C No. - 440500100000087\r\nIFSC code - SRCB0000440', 'B Wing, 202, Sai Miracle Building, Near Akash ganga Society, Shivar Vihar, Rahatani, Pune, Maharashtra.', '27', 'Xform Technologies Pvt Ltd', '27AAGCV1798K1ZN', 'AAGCV1798K', '<p><span style=\"background-color:rgb(255, 255, 255); color:rgb(51, 51, 51); font-family:sans-serif,arial,verdana,trebuchet ms; font-size:13px\">&ldquo;These terms &amp; conditions as mutually agreed between the aforesaid client &amp; Vari Pontoons Pvt Ltd &amp; as being detailed above are strictly confidential and are independent&rdquo;</span></p>\r\n', '', '', '               ', '', '<p>Note</p>\r\n', '8956028951', 'info@varipontoons.com', 1, '<p style=\"text-align:left\">a) Manufacturing will be done as per approved drawing.</p>\r\n\r\n<p style=\"text-align:left\">b) The design, testing, inspection and guarantee certificate (12 months) will be provided.</p>\r\n\r\n<p style=\"text-align:left\">c) Guarantee will depend on site conditions.</p>\r\n\r\n<p style=\"text-align:left\">d) vari Pontoons will be not responsible for any damage/loss in transport, handling or due to natural disastar.&nbsp;</p>\r\n\r\n<p style=\"text-align:left\">e) Transportation, Unloading Installation and commissioning will be in scope of Client if not charged or mentioned in quotation.</p>\r\n', '<p>50%advance, 50% against PI before dispatch, after inspection at our site.</p>\r\n\r\n<p>If there is any delay in payment after clearance of despatch, detention charges will be applicable @0.5% per week of tax invoice.</p>\r\n\r\n<p>Advance payment will not be returnable.</p>\r\n', '<ol>\r\n	<li>Work will be started after receiving PO.</li>\r\n	<li>Manufacturing will be completed within scheduled working day ( 4-6 weeks) (excluding holidays) depending on the material availability. Separate Schedule will be issued after receiving PO along with Advance.</li>\r\n	<li>Validity of quote is 15 days.</li>\r\n</ol>\r\n', '<p>The taxes will be levied as per present government norms as applicable.</p>\r\n', '<ul>\r\n	<li>Any civil work required for installation of pontoon.</li>\r\n	<li>No Modifications in design/construction post start of construction.</li>\r\n	<li>Towing/Transportation post commissioning shall be arranged by Owner.</li>\r\n	<li>Any other item or part or work or supply or service other than quotation.</li>\r\n	<li>We are happy to quote as a turnkey project for your requirement and assure you for delivering a pontoon with all documents and drawing.&nbsp;</li>\r\n</ul>\r\n', '<p>STANDARD TERMS AND CONDITIONS FOR PURCHASE ORDER BETWEEN Vari Pontoons (Vari Pontoons/PURCHASER) AND THE SELLER/VENDOR -&nbsp;<br />\r\nThis Purchase Order is subject to the following terms and conditions, and by accepting this Purchase Order, the Seller/Service Provider agrees to supply the Goods/Services upon these terms and conditions. These terms and conditions shall override any other conditions proposed by the Seller/Service Provider save and in so far as they may have been expressly accepted as variations by the both parties hereto and included in this Purchase Order.<br />\r\n(a) The date stipulated for delivery of the Goods shall be the essence of the Purchase Order, and the Goods to be delivered by the Seller as per the defined schedule provided by BAL, from time to time.<br />\r\n(b) The Seller shall notify the Purchaser when Goods are ready for dispatch and supply as per the Purchase Order.<br />\r\n(c) In the event the Goods are dispatched prior to receipt of written instruction, the Purchaser reserves the right to return the<br />\r\nGoods to the Seller at the Seller&#39;s risk and cost.<br />\r\n(d) The Seller shall be liable for any additional cost incurred by the Purchaser resulting from the Seller&#39;s failure to comply with the Purchase Order requirements including but not limited to documentation, certification, packing, marking, shipment and place of delivery.<br />\r\n(e) The Seller shall provide the Guarantee Certificate/Warranty Certificate/Test Certificate of the Goods wherever required along with the Goods or as may be required by BAL from time to time.<br />\r\nIn the event, the Seller fails to supply the Goods as per delivery schedule mentioned in this Purchase Order or as may be communicated by BAL from time to time, liquidated damages equal to 0.5% of the total order value of the undelivered portion of the Goods per week of delay or part thereof shall be payable by the Seller to BAL subject to maximum 5% of the total order value The Seller agrees and acknowledges that the liquidated damages is a genuine pre-estimate of the loss that may be suffered by BAL as a result of non-compliance by the Seller of the obligations specified in this Purchase Order.<br />\r\n3. Inspection<br />\r\n(a) All Goods provided hereunder shall be subject to inspection and testing at the point of manufacture/destination at any time by BAL or through its representative.<br />\r\n(b) If, in the Purchaser&rsquo;s judgment, any of the Goods are defective or otherwise not in conformity with the requirements set out hereunder, the Purchaser, in additions to its other rights, may (i) reject the same for full credit, (ii) retain the same and remedy any defects of nonconformity at the Purchaser&rsquo;s expense, or (iii) require prompt correction or thereafter be tendered by the Purchaser for acceptance without the Purchaser&rsquo;s written consent. The packing, handling and transportation costs, charges and expenses incident to the Purchaser&rsquo;s exercise of its rights hereunder will be charged to the Seller&rsquo;s account. Nothing herein shall release the Seller from its obligation to fully and adequately test and inspect Goods sold to the Purchaser hereunder.<br />\r\n(c) The Seller shall cooperate and provide assistance as may be required by BAL to carry out the tests at no additional cost to the account of BAL.<br />\r\n4. Samples and Major Quality Deviation<br />\r\n(a) In order to ensure that the Goods which are subject matter of this Purchase Order are delivered to the Purchaser in accordance with the specifications, drawings, and other requirements as provided by the Purchaser to the Seller, an umpire sample shall be taken and be kept in sealed condition in three packets in presence of representatives of both Purchaser and Seller. One umpire sample should be kept with the Seller, second one with the Buyer and third one with an Independent Inspection Agency who will be appointed for the purpose by the Purchaser. This umpire sample will be re-analyzed and finalized if any Major Quality Deviation is found between Load Port, Discharge Port and Balasore Alloys Limited QC analysis.<br />\r\n(b) The term &quot;Major Quality Deviation&quot; shall mean such deviation from the specifications provided by the Purchaser to the Seller at the time of this Purchase Order and shall include such modifications to such specification as may be informed to the Seller from time to time.<br />\r\n(c) The Goods supplied against this Purchase Order should be strictly confirming to drawings, and other requirements as provided by the Purchaser to the Seller, and shall in no manner, in no event and at no time, be beyond the Major Quality Deviation provided by the Purchaser to the Seller. If in view of the Purchaser there occurs any Major Quality Deviation, the same shall be treated as non-compliance with the obligations of the Seller and the consequences of which will include rejection of the Goods so supplied or about to be supplied to the Purchaser unless such Major Quality Deviation is pre-accepted by the Purchaser in writing.<br />\r\n5. Covenants, Representations and Warranties<br />\r\n5.1 The Seller hereby represents, covenants and warrants to BAL that:<br />\r\n(a) all Goods ordered, and/or provided hereunder will conform in all respects to the specifications, drawings, samples and other descriptions set out in this Purchase Order, and will be merchantable, free from any defects and fit and sufficient for the purposes for which the Purchaser intends, and the Goods shall in no manner, in no event and at no time, be beyond the Major Quality Deviation provided by the Purchaser to the Seller;<br />\r\n(b) in addition to any other remedies that the Purchaser may have, the Purchaser may reject Goods not conforming to the foregoing warranties, whether or not such Goods shall have been previously accepted by the Purchaser. In case of rejection due to poor quality on specification ground or for any other reason such that the Goods are not fit for the purpose for which they<br />\r\nare intended, the Seller shall &#39;lift back&rsquo; the Goods within seven days from the date of intimation, at its own cost. It is hereby clarified that BAL shall not be responsible for material cost, freight or any other charges of the rejected Goods;<br />\r\n(c) the Seller shall replace or correct, at the Purchaser&#39;s option and at Seller&#39;s cost, defects of any Goods not conforming to these warranties. If the Seller fails to correct defects in or replace non- conforming Goods within such number of days as may be communicated by BAL, BAL may either (i) make such corrections or replace such Goods and require the Seller to pay for all costs incurred by Purchaser or set-off the same against any money payable by BAL to the Seller, or (ii) revoke its acceptance of the Goods in which event Seller shall be obligated to refund the purchase price and make all necessary arrangements, at Seller&#39;s costs, for the return of the Goods to the Seller;<br />\r\n(d) the Purchaser&#39;s inspection, test, acceptance or use of the Goods shall not affect the Seller&#39;s obligations under these warranties. All warranties of the Seller herein or which are implied by law shall survive any inspection, delivery, acceptance or payment by Purchaser. Any attempt by Seller to limit, disclaim, or restrict these warranties or any remedies of Purchaser, by acknowledgment or otherwise, in accepting or performing this Order, will be null, void, and ineffective without Purchaser&#39;s written consent;<br />\r\n(e) the Seller agrees that it is impossible to measure in money the damages that would be suffered by BAL by reason of the failure by the Seller to perform any of the obligations hereunder;<br />\r\n(f) the Goods shall be guaranteed for trouble free service for a period of 18 months from the date of supply or 12 months from the date of commissioning whichever is earlier. Any defect noticed during this period shall be made good by the Seller free of cost to the satisfaction of BAL;<br />\r\n(g) the Seller has the full power and authority to execute, deliver and perform this Purchase Order and to carry out the transactions contemplated hereby and the Seller is duly incorporated or organised with limited liability and existing under the laws of the jurisdiction of its incorporation or organisation;<br />\r\n(h) the Purchase Order constitutes the legal, valid and binding obligation of the Seller, enforceable against the Seller in accordance with its terms and in terms of law and equity;<br />\r\n(i) the Seller shall during the currency of this Purchase Order, by itself and ensure that, Seller&#39;s employees, workers, servants, agents, subcontractors or suppliers, abide by and conform with such principles of ethics and behaviour as provided in a Code of Conduct (&quot;Code of Conduct&quot;) to the Seller separately, along with the Purchase Order by the Purchaser (receipt of the Code of Conduct is acknowledged herewith by the Seller), and the Seller agrees and acknowledges that such Code of Conduct shall include such modifications as may be informed by the Purchaser to the Seller from time to time.<br />\r\n5.2 The Parties agree that Clause 5.1 shall survive the termination or cancellation of this Purchase Order.<br />\r\n6 Title and Risk<br />\r\n(a) Except as otherwise provided herein, all Goods furnished by the Seller shall become the property of the Purchaser when the first of the following occurs:<br />\r\n(i) When the Purchaser pays for the Goods or part thereof in accordance with the terms of the Purchase Order.<br />\r\n(ii) When the Goods are delivered to the Purchaser.<br />\r\n(b) Notwithstanding anything contained herein, the Seller shall be responsible for and shall bear any and all risk of loss or damage to the Goods until delivery thereof in accordance with the delivery provisions of this Purchase Order. Upon such delivery, risk of loss or damage shall pass to the Seller, provided however, that any loss or damage, whenever occurring, which results from the Seller&#39;s non confirming packaging, crating or handling shall be borne by the Seller.<br />\r\n(c) Seller shall be liable to pay the differential price between the Order price and the market price at which BAL shall procure from the market in respect of quantity not supplied against this Purchase Order.<br />\r\n(d) The Seller warrants that the Goods provided hereunder shall be free and clear of any lien or other adverse claim against title.<br />\r\n(e) The Seller shall insure the Goods at their full replacement value and the Purchaser may require evidence of insurance at their full replacement value, and such insurance shall include transit insurance as may be required by BAL. Only in case of ex-works supply, transit Insurance will be arranged by BAL.<br />\r\n7 Compliance with Applicable Laws<br />\r\nThe Seller warrants that in undertaking the requirements of the Purchase Order, the Seller will comply with all applicable laws and regulations, particularly but not limited to health and safety.<br />\r\nThe Seller shall defend, indemnify and hold harmless the Purchaser against any fine, penalty ad sanction of similar nature which may be imposed on the Purchaser by any government authority by reason of an alleged violation of such laws and/or regulations by the Seller as well as against all claims, suits and proceedings in that respect.<br />\r\n8 Liability<br />\r\nThe aggregate liability of the Seller under this Purchase Order, or otherwise in connection with the obligations to be performed hereunder, shall in no event exceed the total price payable to the Seller hereunder as specified in this Purchase Order. The preceding limitation shall not apply to liability arising as a result of the Seller&rsquo;s fraud or wilful misconduct in performance of the obligations hereunder.<br />\r\n&nbsp;</p>\r\n\r\n<p>Acceptance<br />\r\nThe act of performing any obligation under this Purchase Order by the Seller or payment of any amounts by Vari Pontoons to the Seller shall be deemed acceptance by the Seller of the terms and conditions mentioned in this Purchase Order. The Seller shall sign the duplicate copy of this Purchase Order by affixing its rubber stamp &amp; return the same to Vari Pontoons within 3 working days failing which shall be deemed acceptance by the Seller of the terms and conditions mentioned in this Purchase Order.<br />\r\nSafety clause - You have to comply with all statutory provision, safety management system applicable at work place, and for this you have to seek necessary instructions from respective site in-charges. You also have to comply with safe operating procedure at the instruction of safety officer and respective site in-charges. In case of non-compliance of the same, suitable penalty will be imposed upon you as deemed fit. If risk of health and/or safety of any of the persons is observed because of non-compliance then the work order will be ceased immediately till the non-compliance is corrected. Before start of the job, please ensure that all your workmen must report to Vari Pontoons safety department for training on safety aspect.</p>\r\n\r\n<p>Governing Law and Jurisdiction<br />\r\nThe Purchase Order shall be governed by, and construed in accordance with, the laws of India and the courts at Pune/PCMC, Maharashtra alone shall have exclusive jurisdiction over all disputes arising under, pursuant to and/ or in connection with the Purchase Order.</p>\r\n\r\n<p>Confidentiality<br />\r\n14.1 General Obligation<br />\r\nThe Seller undertakes that it shall not reveal, and shall ensure that its directors, officers, managers, partners, members, employees, legal, financial and professional advisors and bankers (collectively, &quot;Representatives&quot;) do not reveal, to any third party, any Confidential Information without the prior written consent of Vari Pontoons, regardless of whether this Purchase Order is terminated or not. The term &quot;Confidential Information&quot; as used in this Purchase Order means: (a) any information concerning Vari Pontoons, its business, intellectual properties, technology, trade secrets, know-how, finance, transactions or affairs of Vari Pontoons, any subsidiary or any other shareholders or any of their respective affiliates, partners, directors, officers or employees (whether conveyed in written, oral or in any other form and whether such information is furnished before, on or after the date hereof); and (b) any information or materials prepared by Vari Pontoons or its representatives that contains or otherwise reflects, or is generated from, Confidential Information.<br />\r\nExceptions for Credentials -&nbsp;</p>\r\n\r\n<p>The provisions of credential Clause shall not apply to:<br />\r\n(a) disclosure of that is or becomes generally available to the public other than as a result of disclosure by or at the direction of the Seller or any of its Representatives in violation of this Purchase Order;<br />\r\n(b) disclosure by the Seller to its Representatives and affiliates (and their partners, officers and directors) in accordance with this Purchase Order provided such Representatives and affiliates are bound by similar confidentiality obligations;<br />\r\n(c) disclosure by the Seller of Confidential Information concerning Vari Pontoons that is reasonably necessary in the ordinary course of business or otherwise in connection with the obligations required to be performed under this Purchase Order;<br />\r\n(d) obligations of disclosure, after giving prior notice to Vari Pontoons to the extent practicable under the circumstances and subject to any practicable arrangements to protect confidentiality, to the extent required under the governmental regulations or generally accepted accounting standards applicable to any party, any applicable law, or judicial or regulatory process or in connection with any judicial process regarding any legal action, suit or proceeding arising out of or relating to this Purchase Order.<br />\r\n&nbsp;</p>\r\n\r\n<p>Force Majeure<br />\r\n&quot;Force Majeure&quot; shall mean any circumstances beyond the reasonable control of either party, which prevent or impede the supply of Goods hereunder and includes but not limited to the following matters:(a) Acts of God; (b) War or Hostilities; (c) Riot or Civil Commotion; (d) Earthquake, flood, fire or other natural physical disaster. It is clarified that mere shortage of labour, materials or utilities shall not constitute Force Majeure, unless caused by circumstances, which are themselves Force Majeure. Neither party will be responsible for any event of Force Majeure as set out herein.<br />\r\n&nbsp;</p>\r\n\r\n<p>Rights in Specification, Plans, Drawings, Patterns, Etc<br />\r\n(a) Any specifications, plans, drawings, patterns or designs supplied by the Purchaser to the Seller in connection with the Purchase Order shall remain the property of the Purchaser.<br />\r\n(b) Title to all drawings, specifications, calculations and other documents specifically prepared by the Seller in connection with the Goods shall vest in the Purchaser and shall have the right to use these drawings, specifications, calculations and other documents without any obligation of any kind to the Seller.</p>\r\n\r\n<p>Termination, Assignment and Cancellation<br />\r\n(a) Seller&rsquo;s default<br />\r\nIn the event the Seller (i) is insolvent; (ii) makes a general assignment for the benefit of creditors; (iii) admits in writing its inability to pay debts as they mature; (iv) has a trustee or receiver appointed by any court for it or any substantial part of Seller&rsquo;s assets; (v) fails or appears to be unable to perform any of its obligations in accordance with the terms of the Purchase Order, the Purchaser may terminate this Purchase Order in whole or in part and/or pursue any further remedies available at law or in equity. No waiver by the Purchaser of a breach by the Seller of any provision of this Purchase Order shall constitute a waiver of any other breach of such provision. Further, BAL shall have the right at all times to modify, amend, terminate or cancel this Purchase Order in any manner without assigning any reason for the same by giving a written notice to the Seller, for which no compensation/damage shall be paid to the Seller. The Seller shall not have the right to cancel, terminate, amend this Purchase Order, or assign its rights or obligations under this Purchase Order, without the prior written consent of BAL. BAL may assign or sub-let the whole or part of its right, liabilities and obligations to an affiliate, contractor, successor, nominee or bona fide agent upon the same terms and conditions without prior consent the Seller.<br />\r\n(b) Cancellation<br />\r\nIn addition to any other provisions contained herein for the cancellation or termination of this Purchase Order, the Purchaser may cancel this Purchase Order, for any reason or no reason, in whole or in part, by written notice to the Seller, for which no&nbsp;compensation shall be paid to the Seller.</p>\r\n\r\n<p>&nbsp;Indemnity<br />\r\nNotwithstanding anything contained herein, the Seller shall indemnify, defend, and hold BAL and its affiliates harmless from and against any or all claims, demands, litigation or proceedings of whatever kind, whether based upon negligence, breach of express or implied warranty, and from and against all direct and indirect damages of every kind whatsoever, arising out of, by reason of, or in any way connected with the any breach by the Seller of any of its obligations, or representation or warranty hereunder, or any other act, omission or negligence of the Seller or any of Seller&#39;s employees, workers, servants, agents, subcontractors or suppliers.<br />\r\n10 Changes<br />\r\n(a) The Purchaser will have the right to make changes to this Purchaser Order at all times, including changes to drawings, designs, configurations, specifications, quantities, methods of shipment or packing and delivery schedules or locations of delivery.<br />\r\n(b) If any such changes cause an increase or decrease in the cost of or the time required for the performance of any work under this Order, an equitable adjustment will be made in the contract price or delivery schedule, or both, and this Purchaser Order will be modified in writing accordingly.<br />\r\n(c) Any claim by the Seller for adjustment under this clause must be in a detailed writing and delivered to Purchaser within 7 days after the date the Seller receives notification of such change. Any change will be authorized only by a duly executed amendment to this Purchaser Order.<br />\r\n(d) Information, such as technical information or guidance provided to the Seller by representatives of the Purchaser will not be construed as a change within the meaning of this Section. If the Seller considers that the conduct of any of the Purchaser&#39;s employees has constituted a change under this Purchase Order, the Seller will immediately notify Purchaser in writing as to the nature of the change and any proposed adjustment, which will then be subject to this clause.<br />\r\nCODE OF CONDUCT<br />\r\n1. PREAMBLE<br />\r\n1.1 This Code of Conduct (&quot;Code&quot;) shall be fulfilled and adhered to, during the course of dealing between the Seller and Balasore Alloys Limited (hereinafter referred to as &quot;Company&quot;), in the course of performance of obligations by the Seller under the Purchase Order.<br />\r\n1.2 This Code is in alignment with Company&rsquo;s vision and values to achieve the mission &amp; objectives and aims at enhancing ethical and transparent process in managing the affairs of the Company.<br />\r\n2. THE CODE<br />\r\nThe Seller shall fulfil following obligations:<br />\r\n2.1 The Seller is expected to respect and abide by this Code and to be transparent and not intentionally mislead the Company in the course of their business.<br />\r\n2.2 The Seller must undertake to fully and willingly to co-operate with the Company with respect to execution of all the provisions under the respective Purchase Order.<br />\r\n2.3 The Seller and its employees or agents shall ensure highest level of trust, honesty and integrity.<br />\r\n2.4 That there can be no compromise in standards of adherence and any person who violates this Code shall be summarily dissociated.<br />\r\n2.5 The Seller shall not take any recourse to any unethical behavior (implicit or explicit) with any employee or representative or authorised person of the Company for the purpose of obtaining a purchase order or any information that may result in a favorable financial impact to the Seller and specifically:<br />\r\n(a) shall not offer or accept bribe or use other means of obtaining undue or improper advantage. The Seller, or its representatives or employees, shall not offer to any employee of the Company a kickback, favor, gratuity, or anything of value to obtain favorable treatment or for the advancement of business;<br />\r\n(b) shall not take any advantage of any family / social / political connections in obtaining favor with regard to any purchase order and merit shall be the sole attribute for association with the Company;<br />\r\n(c) shall not offer any gift or entertainment for the purpose of obtaining a purchase order or any undue favor.<br />\r\n2.6 The Seller shall desist from unfair trade practices with the Seller&rsquo;s competitors who are also associated with the Company.<br />\r\n2.7 The highest standards of care must be maintained by the Seller in terms of its business interactions and must have a zero tolerance policy towards any and all forms of bribery, corruption, extortion and embezzlement, etc.<br />\r\n2.8 All business dealings with the Company should be performed transparently and must be accurately recorded on the Seller&rsquo;s business books and records.<br />\r\n2.9 The Seller must protect and not infringe with any intellectual property/ information/ technology of the Company which comes to the Seller&rsquo;s knowledge during the course of the Seller&rsquo;s business relationship/ dealings with the Company.<br />\r\n2.10 The Seller must abstain from undertaking any form of action which could potentially cause a material adverse effect to the goodwill and reputation of the Company on account of their commercial relationship.<br />\r\n2.11 The Seller must uphold the standards of fair business, advertising and competition.<br />\r\n3. AMENDMENT TO THE CODE<br />\r\nThe provisions of this Code can be amended /modified by the Company from time to time and all such amendments/modifications shall take effect from the date of the Purchase Order.<br />\r\n&nbsp;</p>\r\n', '<p>Payment Terms</p>\r\n', '<p>Process Schedule</p>\r\n', '<p>Taxes and duties are applicable as per rule on the date of supply/ date of payment under the applicable law.</p>\r\n', '<p>Exclusions</p>\r\n', '', NULL, NULL);
